"use client"

import { MODULES } from "@/lib/modules"
import { Blocks, BookOpen, CheckCircle2, FileBarChart, Mail, Percent, Settings, ShieldCheck, Users, Wand2, Webhook } from "lucide-react"
import Link from "next/link"
import { usePathname } from "next/navigation"

const ICONS: Record<string, typeof Settings> = {
  workflow: Wand2,
  percent: Percent,
  "check-circle": CheckCircle2,
}

/** The settings sub-nav: every destination the sidebar used to list as its own flat link, now
 * tabs across the top of a settings page instead — the sidebar collapses them to a single
 * "Settings" entry (components/shell/sidebar.tsx). Same destinations, reorganized navigation,
 * no new pages. Rendered by the (chrome) layout only for settings/* routes. */
export function SettingsNav({ workspaceId, enabledModuleKeys, integrationsEnabled = false }: {
  workspaceId: string
  enabledModuleKeys: string[]
  integrationsEnabled?: boolean
}) {
  const pathname = usePathname()
  const base = `/workspaces/${workspaceId}/settings`
  if (!pathname.startsWith(base)) return null
  const enabled = new Set(enabledModuleKeys)
  const moduleItems = MODULES
    .filter((module) => enabled.has(module.key))
    .flatMap((module) => module.navItems ?? [])
    .filter((item) => item.href.startsWith("settings/"))
    .map((item) => ({ href: `/workspaces/${workspaceId}/${item.href}`, label: item.label, icon: ICONS[item.icon] ?? Settings }))

  const items = [
    { href: `${base}/workspace`, label: "Workspace", icon: Users },
    { href: `${base}/modules`, label: "Modules", icon: Blocks },
    ...moduleItems,
    { href: `${base}/templates`, label: "Templates", icon: Settings },
    { href: `${base}/reports`, label: "Reports", icon: FileBarChart },
    { href: `${base}/email`, label: "Email intake", icon: Mail },
    { href: `${base}/security`, label: "Security", icon: ShieldCheck },
    ...(integrationsEnabled ? [
      { href: `${base}/integrations`, label: "Integrations", icon: Webhook },
      { href: `${base}/accounting-mapping`, label: "Account mapping", icon: BookOpen },
    ] : []),
  ]

  return <nav className="mb-6 flex flex-wrap gap-1 border-b pb-3">
    {items.map((item) => {
      const active = pathname === item.href || pathname.startsWith(`${item.href}/`)
      return <Link key={item.href} href={item.href} aria-current={active ? "page" : undefined}
        className={`inline-flex items-center gap-1.5 rounded-md px-2.5 py-1.5 text-sm font-medium transition-colors ${active ? "bg-slate-100 text-emerald-800" : "text-slate-600 hover:bg-slate-100/60 hover:text-slate-900"}`}>
        <item.icon className="h-4 w-4 shrink-0" />{item.label}
      </Link>
    })}
  </nav>
}

"use client"

import { AccountMenu } from "@/components/shell/account-menu"

import { SwitchableWorkspace, WorkspaceSwitcher } from "@/components/workspace/switcher"
import { BiteMark } from "@/components/marketing/logo"
import { WorkspacePulse } from "@/components/shell/workspace-pulse"
import { MODULES } from "@/lib/modules"
import { isUnpluggedPath } from "@/lib/unplugged"
import { AlertTriangle, CheckCircle2, ClipboardCheck, Files, HeartPulse, History, Landmark, Library, PanelLeftClose, PanelLeftOpen, Percent, Receipt, Settings, Wallet, Workflow, Zap } from "lucide-react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { useEffect, useState } from "react"

const RAIL_PIN_KEY = "docubite.rail.pinned"
const QUEUE_SEGMENTS = ["invoices", "purchase-orders", "receipts", "bank-statements", "exceptions"]

/** Maps a ModuleDefinition.navItems[].icon string (lib/modules) to the lucide component it names.
 * A string in the registry rather than the component itself keeps lib/modules free of a React/UI
 * dependency — it's read by server code (capabilities, seeds) that has no business importing icons.
 * Settings-tagged module items (Rules, Tax, Approvals) don't render here at all — they show up in
 * components/shell/settings-nav.tsx instead, and unplugged surfaces (lib/unplugged) never render. */
const ICONS: Record<string, typeof Files> = {
  inbox: ClipboardCheck,
  "heart-pulse": HeartPulse,
  zap: Zap,
  "check-circle": CheckCircle2,
  workflow: Workflow,
  percent: Percent,
  receipt: Receipt,
  wallet: Wallet,
}

/** The workspace rail — a flat spine of destinations, no section captions. The primary group is
 * labelled `TODAY` (a verb-flavoured intent label, not a container word); its badge counts are the
 * promise the label keeps. When every primary is quiet the label drops one notch and a "you're
 * caught up" line takes over, so an empty rail reads as a win rather than a vacuum.
 *
 * Four typed intake destinations sit in two peer pairs, followed by Exceptions, Controls, Finance
 * and Archive. There is no Dashboard entry: the workspace home is the Invoices queue (#238), and
 * the logo goes there. The entries keep identical weight and badge treatment; a hairline break
 * separates the matching pair from the receipts/reconciliation pair without adding another
 * caption to the rail.
 *
 * On sheet-mode and document-detail pages the rail replaces its icon column with a
 * <WorkspacePulse /> card — a mini-map of the workspace's living state, three rows mirroring the
 * three primaries with the same badges. The workspace stays visibly alive inside those surfaces
 * instead of vanishing behind the door of a full-screen room. */
export function Sidebar({ workspaceId, workspaces, user, enabledModuleKeys, accountingEnabled = false, pipelineReviewCount = 0, reviewTaskCount = 0, financePushableCount = 0, openExceptionsCount = 0 }: {
  workspaceId: string
  workspaces: SwitchableWorkspace[]
  user: { name: string; email: string }
  /** Every module key currently enabled for this workspace (getWorkspaceCapabilities(...).enabled),
   * used to build the nav entries each module registers via ModuleDefinition.navItems. */
  enabledModuleKeys: string[]
  /** config.integrations.bigcapital.enabled — a deployment-level gate for whether Finance is a
   * live destination on this rail. */
  accountingEnabled?: boolean
  /** counts.to_review from countDocumentsByStage — surfaced on Documents so "something needs you"
   * is visible from every page. */
  pipelineReviewCount?: number
  /** countOpenReviewTasks — retained on the prop signature for API stability; not surfaced as its
   * own rail badge, since pipelineReviewCount already carries that signal on Invoices. */
  reviewTaskCount?: number
  /** counts.approved from countDocumentsByStage — documents past review, waiting to push to the
   * ledger. Only meaningful when accountingEnabled is true. */
  financePushableCount?: number
  /** #210: open+in_review escalated-check count — countOpenExceptions. */
  openExceptionsCount?: number
}) {
  void reviewTaskCount
  const pathname = usePathname()
  const base = `/workspaces/${workspaceId}`
  // #238: the workspace home is the Invoices queue; link there directly rather than through the
  // index route's redirect.
  const home = `${base}/invoices`

  // #225: on a Queue screen (and its `/<queue>/<id>` deep links, which render the same screen)
  // the rail collapses to a 56px icon rail so the queue gets the work area. It expands over the
  // content on hover or keyboard focus, and a pin toggle keeps it expanded; the pin is a
  // per-browser convenience, so it lives in localStorage rather than the workspace.
  const isQueue = QUEUE_SEGMENTS.some((segment) => pathname === `${base}/${segment}` || pathname.startsWith(`${base}/${segment}/`))
  const [pinned, setPinned] = useState(false)
  useEffect(() => {
    // Read after hydration (the server can't know the browser's pin), off the effect's own tick.
    const id = window.setTimeout(() => {
      try { setPinned(window.localStorage.getItem(RAIL_PIN_KEY) === "1") } catch { /* private mode: stay unpinned */ }
    }, 0)
    return () => window.clearTimeout(id)
  }, [])
  const togglePin = () => setPinned((current) => {
    const next = !current
    try { window.localStorage.setItem(RAIL_PIN_KEY, next ? "1" : "0") } catch { /* ignore */ }
    return next
  })
  const compact = isQueue && !pinned

  // Sheet and document-detail pages get the mini-map treatment. The rail keeps its full 236px
  // width — the pulse card + secondaries + bottom items need it — but its contents change: pulse
  // card in place of the main nav column. Users staying on any other page get the classic rail.
  // A typed deep link (`/invoices/<id>`) is a Queue screen since #225, not an immersive page.
  const isImmersive = !isQueue && (pathname.endsWith("/sheet") || pathname.includes("/documents/") || pathname.includes("/library/documents/"))
  const enabled = new Set(enabledModuleKeys)
  const moduleWorkItems = MODULES
    .filter((module) => enabled.has(module.key))
    .flatMap((module) => module.navItems ?? [])
    .filter((item) => !item.href.startsWith("settings/") && item.href !== "health" && !isUnpluggedPath(`${base}/${item.href}`))
    .map((item) => ({ href: `${base}/${item.href}`, label: item.label, icon: ICONS[item.icon] ?? Files, exact: false }))

  // Controls (the touchless-automation module's nav item) is hoisted out of the module bucket
  // into the primary spine, directly under the typed intake group: it is the levers that govern the document
  // pipeline, so adjacency to the pipeline it controls is the information architecture.
  const controlsItem = moduleWorkItems.find((item) => item.href === `${base}/automation`)
  // The review-queue module's "Review" item is dropped (#238): since #225 every queue is the
  // review surface, so a second entry for the same job was a second grammar.
  const otherModuleItems = moduleWorkItems.filter((item) => item.href !== `${base}/review` && item.href !== `${base}/automation`)

  // Primary spine, in workflow order: the four typed intake destinations, then Exceptions
  // (escalated work needing attention, per #210 — organize: same tier as the typed destinations
  // by weight/badge treatment, not paired with any of them since it has no document-type sibling
  // and cuts across all four), then Controls (their governing levers), Finance (booked outcome),
  // and Archive (the permanent record everything lands in) closing the group.
  const typedDestinationGroups = [
    [
      { href: `${base}/invoices`, label: "Invoices", icon: Receipt, exact: false },
      { href: `${base}/purchase-orders`, label: "Purchase Orders", icon: ClipboardCheck, exact: false },
    ],
    [
      { href: `${base}/receipts`, label: "Receipts", icon: Receipt, exact: false },
      { href: `${base}/bank-statements`, label: "Bank Statements", icon: Landmark, exact: false },
    ],
  ]
  const exceptionsItem = { href: `${base}/exceptions`, label: "Exceptions", icon: AlertTriangle, exact: false, badge: openExceptionsCount > 0 ? openExceptionsCount : undefined }
  const primaryItems = [
    exceptionsItem,
    ...(controlsItem ? [controlsItem] : []),
    ...(accountingEnabled ? [{ href: `${base}/finance`, label: "Finance", icon: Landmark, exact: false, badge: financePushableCount > 0 ? financePushableCount : undefined }] : []),
    // "Archive" is the accountant's own word for the permanent source-document record (Dext and
    // Hubdoc both name this surface Archive). Route stays /library — same label-over-URL stance
    // as Controls (/automation) and Finance's /accounting redirect.
    { href: `${base}/library`, label: "Archive", icon: Library, exact: false, tourTarget: "library" as const },
  ]

  // Secondary destinations: per-workspace module extras only. Under a hairline, no caption — the
  // divider is the sectioning.
  const secondaryItems = otherModuleItems

  const bottomItems = [
    { href: `${base}/settings/workspace`, label: "Settings", icon: Settings, exact: false },
    { href: `${base}/activity`, label: "Activity", icon: History, exact: false },
    { href: `${base}/health`, label: "Health Checks", icon: HeartPulse, exact: false },
  ]

  // Sum across primary badges tells us whether the TODAY label is a promise or a reward. When the
  // total is zero every primary is quiet, and the "you're caught up" line reads under the group
  // instead of a promise the badges are supposed to keep.
  const todayTotal = (pipelineReviewCount || 0) + (accountingEnabled ? (financePushableCount || 0) : 0) + (openExceptionsCount || 0)

  const isActive = (item: { href: string; label: string; exact: boolean }) => item.exact
    ? pathname === item.href
    : pathname === item.href || pathname.startsWith(`${item.href}/`)
      || (item.label === "Settings" && pathname.startsWith(`${base}/settings`))
      // Ingestion and review are still reachable through the typed destinations. Keep the first
      // destination lit for those legacy/generic work surfaces until their queues are migrated.
      || (item.label === "Invoices" && (pathname.startsWith(`${base}/pipeline`) || pathname.startsWith(`${base}/documents`) || pathname.startsWith(`${base}/review`) || pathname.startsWith(`${base}/bills`)))
      || (item.label === "Invoices" && pathname.startsWith(`${base}/invoices`))
      || (item.label === "Purchase Orders" && pathname.startsWith(`${base}/purchase-orders`))
      || (item.label === "Receipts" && pathname.startsWith(`${base}/receipts`))
      || (item.label === "Bank Statements" && pathname.startsWith(`${base}/bank-statements`))
      // Finance keeps its rail lit on the legacy /accounting URL too, which redirects here.
      || (item.label === "Finance" && pathname.startsWith(`${base}/accounting`))

  // In the compact rail every label is hidden until the rail expands (hover / focus-within /
  // pin), and the link keeps a `title` so a hover over the icon alone still names it. The badge
  // stays visible in both widths — it is the promise the TODAY group makes — as a small count
  // pinned to the icon's corner while collapsed.
  const labelClass = compact ? "hidden group-hover/rail:inline group-focus-within/rail:inline" : ""
  const navLink = (item: { href: string; label: string; icon: typeof Files; exact: boolean; badge?: number; tourTarget?: string }) => {
    const active = isActive(item)
    return <Link key={item.href} href={item.href} aria-current={active ? "page" : undefined} title={compact ? item.label : undefined}
      {...(item.tourTarget ? { "data-tour-target": item.tourTarget } : {})}
      className={`relative flex items-center gap-2.5 rounded-md px-2.5 py-1.5 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 ${active ? "bg-white text-emerald-800 shadow-sm ring-1 ring-emerald-700/10" : "text-slate-600 hover:bg-slate-300/40 hover:text-slate-900"}`}>
      {active && <span className="absolute left-0 top-2 bottom-2 w-[3px] rounded-full bg-emerald-700" />}
      <span className="relative shrink-0">
        <item.icon className="h-4 w-4" />
        {compact && item.badge != null && <span aria-hidden className="absolute -right-2 -top-1.5 flex h-[15px] min-w-[15px] items-center justify-center rounded-full bg-indigo-600 px-0.5 text-[10px] font-bold text-white tabular-nums group-hover/rail:hidden group-focus-within/rail:hidden">{item.badge > 99 ? "99+" : item.badge}</span>}
      </span>
      <span className={`truncate ${labelClass}`}>{item.label}</span>
      {item.badge != null && <span className={`ml-auto flex h-[19px] min-w-[19px] items-center justify-center rounded-full bg-indigo-600 px-1 text-[11px] font-bold text-white tabular-nums transition-[background-color] duration-200 ${labelClass}`}>{item.badge > 99 ? "99+" : item.badge}</span>}
      {compact && item.badge != null && <span className="sr-only">{item.badge} waiting</span>}
    </Link>
  }

  // TODAY caption. Muted uppercase, small — a promise the badges keep. When totalToday is 0 the
  // caption goes one step quieter and the "caught up" line under the group carries the meaning.
  const todayLabel = <div className={`mb-1 px-2.5 pt-1 text-[11px] font-bold uppercase tracking-[0.08em] text-slate-600 ${compact ? "hidden group-hover/rail:block group-focus-within/rail:block" : ""}`}>Today</div>

  // Compact: the aside holds a 56px slot in the flow; the panel inside it widens over the
  // content on hover/focus so the queue never reflows while the operator glances at a label.
  return <aside className={`group/rail relative hidden shrink-0 md:flex ${compact ? "w-14" : "w-[236px]"}`}>
  <div className={`flex flex-col gap-0.5 border-r border-slate-200 bg-slate-100 py-3.5 transition-shadow duration-150 ease-out ${compact ? "absolute inset-y-0 left-0 z-30 w-14 overflow-hidden px-2 group-hover/rail:w-[236px] group-hover/rail:px-3 group-hover/rail:shadow-[8px_0_24px_-16px_rgba(15,23,42,0.35)] group-focus-within/rail:w-[236px] group-focus-within/rail:px-3 group-focus-within/rail:shadow-[8px_0_24px_-16px_rgba(15,23,42,0.35)]" : "w-full px-3"}`}>
    <Link href={home} className="flex items-center gap-2 px-1.5 py-1" aria-label="DocuBite home">
      <BiteMark className="h-7 w-7 shrink-0" />
      <span className={`truncate text-sm font-bold font-display text-slate-900 ${labelClass}`}>DocuBite</span>
    </Link>

    <div className={`mb-1 mt-2 ${compact ? "hidden group-hover/rail:block group-focus-within/rail:block" : ""}`}><WorkspaceSwitcher workspaces={workspaces} workspaceId={workspaceId} /></div>

    <nav className="mt-2 flex flex-1 flex-col" aria-label="Workspace">
      {isImmersive ? (
        // Immersive mode: the pulse card takes the primary column. Same three peers, but they
        // report status rather than list themselves — the destinations are still reachable, but
        // now they show a heartbeat too. Secondary items collapse to a small icon strip below the
        // pulse; bottom items stay in the same position on the rail.
        <WorkspacePulse
          workspaceId={workspaceId}
          documentsCount={pipelineReviewCount}
          financeCount={financePushableCount}
          accountingEnabled={accountingEnabled}
        />
      ) : (
        <>
          {todayLabel}
          <div className="space-y-1">
            {typedDestinationGroups.map((group, index) => (
              <div key={index} role="group" aria-label={index === 0 ? "Invoices and purchase orders" : "Receipts and bank statements"} className={index === 1 ? "border-t border-slate-200/80 pt-1" : "space-y-0.5"}>
                {group.map(navLink)}
              </div>
            ))}
            <div className="space-y-0.5">{primaryItems.map(navLink)}</div>
          </div>
          {todayTotal === 0 && <p className={`mt-1 px-2.5 text-[11px] font-medium text-slate-500 ${compact ? "hidden group-hover/rail:block group-focus-within/rail:block" : ""}`}>You&apos;re caught up.</p>}
        </>
      )}

      {secondaryItems.length > 0 && <>
        <div className="my-3 border-t border-slate-200/80" aria-hidden="true" />
        <div className="space-y-0.5">{secondaryItems.map(navLink)}</div>
      </>}

      <div className="mt-auto space-y-0.5">
        {bottomItems.map(navLink)}
        {isQueue && <button type="button" onClick={togglePin} aria-pressed={pinned} title={pinned ? "Collapse the rail" : "Keep the rail open"}
          className="flex w-full items-center gap-2.5 rounded-md px-2.5 py-1.5 text-sm font-medium text-slate-600 transition-colors hover:bg-slate-300/40 hover:text-slate-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600">
          {pinned ? <PanelLeftClose className="h-4 w-4 shrink-0" /> : <PanelLeftOpen className="h-4 w-4 shrink-0" />}
          <span className={`truncate ${labelClass}`}>{pinned ? "Collapse rail" : "Keep rail open"}</span>
        </button>}
      </div>
    </nav>

    <div className="mt-auto pt-3">
      <AccountMenu name={user.name} email={user.email} collapsed={compact} />
    </div>
  </div>
  </aside>
}

import { STAGE_LABELS, PIPELINE_STAGES, type PipelineStage } from "@/lib/documents/stages"
import type { AutonomyLevel } from "@/models/automation-config"
import { ArrowRight, Banknote, CheckCircle2, Inbox, SearchCheck, Send } from "lucide-react"
import Link from "next/link"
import { Fragment, type ComponentType, type ReactNode } from "react"

/** The map between the two surfaces: the same five Documents stages, in the same order with the
 * same icons the pipeline's own StageTabs draws, with each handoff annotated by the control that
 * decides it. Documents is the belt; Controls is the control room — this band is the one place
 * both are drawn as a single object, so a reader never has to reconstruct the relationship from
 * two disconnected screens.
 *
 * The annotation IS the connector: a lever governs a transition, so it sits on the joint rather
 * than in a legend. Synced → Paid carries no lever — the ledger confirms payment, nothing here
 * decides it — and drawing that honestly (a plain joint) is part of the map. */

const STAGE_ICONS: Record<PipelineStage, ComponentType<{ className?: string }>> = {
  inbox: Inbox,
  review: SearchCheck,
  approved: CheckCircle2,
  synced: Send,
  paid: Banknote,
}

const LEVEL_LABELS: Record<AutonomyLevel, string> = {
  suggest: "Suggest — a person publishes",
  auto: "Auto with approval",
  touchless: "Touchless",
}

type Joint = {
  /** The stage this joint leads INTO — rendered before that stage's node. */
  before: PipelineStage
  label: string
  /** Null = no lever governs this handoff (Synced → Paid: the ledger confirms payment). */
  href: string | null
}

export function ControlsSpine({ workspaceId, counts, visibleStages, level, minConfidence, canOpenSettings }: {
  workspaceId: string
  counts: Record<PipelineStage, number>
  /** Mirrors the pipeline's own visibleStages rule so the two surfaces never disagree about
   * whether Synced/Paid exist for this workspace. */
  visibleStages: readonly PipelineStage[]
  level: AutonomyLevel
  minConfidence: number
  /** Settings is owner-only; a member's autonomy annotation stays informative but unlinked. */
  canOpenSettings: boolean
}) {
  const base = `/workspaces/${workspaceId}`
  const autonomyLabel = level === "touchless"
    ? `Touchless · ≥ ${minConfidence.toFixed(2)}`
    : LEVEL_LABELS[level]

  const joints: Joint[] = [
    { before: "review", label: "Vendor rules", href: `${base}/automation/vendors` },
    { before: "approved", label: "Approval workflows", href: `${base}/automation/approvals` },
    { before: "synced", label: autonomyLabel, href: canOpenSettings ? `${base}/automation/settings` : null },
    { before: "paid", label: "Ledger confirms payment", href: null },
  ]
  const jointBefore = (stage: PipelineStage) => joints.find((j) => j.before === stage)

  const stageNode = (stage: PipelineStage) => {
    const Icon = STAGE_ICONS[stage]
    return <Link
      href={`${base}/pipeline?stage=${stage}`}
      className="group flex shrink-0 items-center gap-1.5 rounded px-1 py-0.5 hover:bg-slate-50"
    >
      <Icon className="h-4 w-4 shrink-0 text-slate-400 group-hover:text-slate-600" aria-hidden="true" />
      <span className="text-[13px] font-medium text-slate-800 group-hover:text-slate-900">{STAGE_LABELS[stage]}</span>
      <span className="text-[13px] font-semibold tabular-nums text-slate-500">{counts[stage]}</span>
    </Link>
  }

  // `block w-full` is load-bearing: a bare centered flex child sizes to its own content and never
  // wraps or clips against its slot — it just bleeds over its neighbors. Wrapping (not truncating)
  // is the right failure mode for a 2-4 word label: "Approval workflows" as two short lines stays
  // fully legible; the same label ellipsized to "Approva…" does not.
  // Screen-reader context for a joint's link. Read as ink, "Approval workflows" is the shortest
  // legible label; read in tab order with no visible spatial cues, the same string is context-free.
  // Naming the handoff it governs closes that gap without lengthening the visible label at all.
  const jointAria = (joint: Joint): string => {
    const idx = PIPELINE_STAGES.indexOf(joint.before)
    const from = idx > 0 ? STAGE_LABELS[PIPELINE_STAGES[idx - 1]] : STAGE_LABELS[joint.before]
    const to = STAGE_LABELS[joint.before]
    return `${joint.label} — governs the handoff from ${from} to ${to}`
  }

  const annotation = (joint: Joint): ReactNode => joint.href
    ? <Link href={joint.href} aria-label={jointAria(joint)} className="block w-full text-[11px] font-medium leading-tight text-emerald-700 underline-offset-2 hover:text-emerald-800 hover:underline">{joint.label}</Link>
    : <span className="block w-full text-[11px] leading-tight text-slate-400" aria-label={jointAria(joint)}>{joint.label}</span>

  // A real CSS grid, not flexbox, for the desktop band — annotations that wrap to two lines must
  // never push the arrow row out of alignment across columns. A grid's rows size independently:
  // row 1 (annotations) can grow as tall as its tallest wrapped label without affecting row 2's
  // height at all, so the stage icons and the connecting line stay on one shared line regardless
  // of which joint's label happens to wrap. Column template alternates auto (a stage node, sized
  // to its content) and 1fr (a joint, sized to share the remaining space evenly).
  const columns = visibleStages.map((_, i) => (i < visibleStages.length - 1 ? "auto minmax(0,1fr)" : "auto")).join(" ")

  // Below lg: (1024px) — checked against the app's real persistent sidebar, not a bare viewport —
  // there isn't reliably enough width for five stage nodes and four joints on one line even with
  // wrapping annotations; the vertical layout, already full-width per row, reads better there.
  return <div>
    <div className="hidden lg:grid lg:gap-y-1.5" style={{ gridTemplateColumns: columns }}>
      {visibleStages.map((stage, index) => {
        const col = index * 2 + 1
        const joint = jointBefore(stage)
        return <Fragment key={stage}>
          <div style={{ gridColumn: col, gridRow: 2 }} className="flex items-center">{stageNode(stage)}</div>
          {index < visibleStages.length - 1 && <>
            <div style={{ gridColumn: col + 1, gridRow: 1 }} className="flex items-end justify-center px-2 pb-1 text-center">
              {joint ? annotation(joint) : <span className="text-[11px] text-transparent" aria-hidden="true">·</span>}
            </div>
            <div style={{ gridColumn: col + 1, gridRow: 2 }} className="flex items-center px-2" aria-hidden="true">
              <span className="h-px flex-1 bg-[#dbe3ec]" />
              <ArrowRight className="h-3 w-3 shrink-0 text-slate-300" />
            </div>
          </>}
        </Fragment>
      })}
    </div>

    {/* Below lg: the same spine top-to-bottom, annotations indented under each joint. */}
    <div className="flex flex-col lg:hidden">
      {visibleStages.map((stage, index) => {
        const joint = jointBefore(stage)
        return <span key={stage} className="contents">
          {index > 0 && <span className="ml-[7px] flex min-w-0 items-center gap-2.5 border-l border-[#dbe3ec] py-1.5 pl-4">
            {joint && <span className="min-w-0 flex-1 text-left">{annotation(joint)}</span>}
          </span>}
          {stageNode(stage)}
        </span>
      })}
    </div>
  </div>
}

import { getCurrentUser } from "@/lib/auth"
import { getAutomationMetrics } from "@/lib/analytics/workspace-analytics"
import { getWorkspaceCapabilities, requireModule } from "@/lib/modules/capabilities"
import { PIPELINE_STAGES } from "@/lib/documents/stages"
import { deriveAutonomyLevel, getOrCreateAutomationConfig } from "@/models/automation-config"
import { countDocumentsByStage } from "@/models/documents"
import { countOpenReviewTasks } from "@/models/review-tasks"
import { requireWorkspaceRole } from "@/models/workspaces"
import { AutomationFrame, Figure, Funnel, Ledger, LedgerRow, Panel } from "@/components/automation/automation-ui"
import { ControlsSpine } from "@/components/automation/controls-spine"
import Link from "next/link"

export const dynamic = "force-dynamic"

export default async function AutomationDashboardPage({ params }: {
  params: Promise<{ workspaceId: string }>
}) {
  const { workspaceId } = await params
  const user = await getCurrentUser()
  const membership = await requireWorkspaceRole(workspaceId, user.id)
  await requireModule(workspaceId, "touchless-automation")

  const capabilities = await getWorkspaceCapabilities(workspaceId)
  const reviewEnabled = capabilities.has("review-queue")
  const [metrics, reviewCount, stageCounts, config] = await Promise.all([
    getAutomationMetrics(workspaceId, 30),
    reviewEnabled ? countOpenReviewTasks(workspaceId) : 0,
    countDocumentsByStage(workspaceId),
    getOrCreateAutomationConfig(workspaceId),
  ])
  // Mirrors pipeline/page.tsx's visibleStages rule so the two surfaces never disagree about
  // whether Synced/Paid exist for this workspace.
  const showLedgerStages = capabilities.has("accounting-push") || stageCounts.synced > 0 || stageCounts.paid > 0
  const visibleStages = showLedgerStages ? PIPELINE_STAGES : PIPELINE_STAGES.filter((s) => s !== "synced" && s !== "paid")

  const touchlessPercent = Math.round(metrics.touchless.touchlessRate * 100)
  const matchPercent = Math.round(metrics.matchCoverage.matchRate * 100)
  const extracted = metrics.touchless.totalExtracted
  const share = (n: number) => (extracted > 0 ? n / extracted : 0)
  const autonomyLevel = deriveAutonomyLevel(config)

  // Named diagnosis for "why isn't anything flowing untouched?" — the page's primary question,
  // which the old grid never answered. Every claim here reads from `stageCounts` (live), the
  // same source the spine draws from, so the diagnosis can never contradict the map it sits
  // under. Ranked by which lever a reader can pull first: a review backlog outranks an autonomy
  // setting outranks a vendor problem, because clearing blockers moves numbers immediately.
  // `null` means untouched flow is working as configured and no diagnosis is needed.
  const diagnosis: { text: string; href: string; linkLabel: string } | null = (() => {
    if (extracted === 0) return null
    if (touchlessPercent > 0) return null
    if (stageCounts.review > 0) return {
      text: `${stageCounts.review} document${stageCounts.review === 1 ? "" : "s"} waiting in Review. Clear them, or adjust the rule that flagged them.`,
      href: `/workspaces/${workspaceId}/pipeline?stage=review`,
      linkLabel: "Open Review",
    }
    if (autonomyLevel === "suggest") return {
      text: "Autonomy is set to Suggest, so a person must publish every document. Raise it to Auto or Touchless to let clean documents flow.",
      href: `/workspaces/${workspaceId}/automation/settings`,
      linkLabel: membership.role === "owner" ? "Open Settings" : "Ask an owner",
    }
    return {
      text: "No vendor has earned trust yet, so every document goes to a person. Vendors start clearing that bar after their first few reviewed documents.",
      href: `/workspaces/${workspaceId}/automation/vendors`,
      linkLabel: "See Vendor rules",
    }
  })()

  // Collapse rules for dead-weight panels. When a whole ledger's numbers are all zero it does
  // not deserve a full three-row block; a single quiet line names the state and gets out of the
  // way, so the eye finds the objects that actually carry a number.
  const policyTotal = metrics.policyVerdicts.pass + metrics.policyVerdicts.violation + metrics.policyVerdicts.error
  const matchTotal = metrics.matchCoverage.totalDocuments

  return <AutomationFrame
    workspaceId={workspaceId}
    active="metrics"
    reviewCount={reviewCount}
    reviewEnabled={reviewEnabled}
    showSettings={membership.role === "owner"}
    status="Rules that decide which documents move on their own and which wait for a person."
  >
    <Panel title="The pipeline and its levers">
      <ControlsSpine
        workspaceId={workspaceId}
        counts={stageCounts}
        visibleStages={visibleStages}
        level={autonomyLevel}
        minConfidence={config.minConfidence}
        canOpenSettings={membership.role === "owner"}
      />
    </Panel>

    {/* Adaptive layout. Three shapes, one per state:
     *   1. Nothing extracted — a single instruction, no panels.
     *   2. Extracted but nothing flowed untouched yet — the 0%, the diagnosis, one link. The
     *      breakdown panels are hidden entirely: everything they would say is either 0 (noise)
     *      or already stated by the diagnosis.
     *   3. Something did flow — the full report, with each panel scope-labelled "in the last 30
     *      days" to end the "is this live or a snapshot?" confusion that broke trust before. */}
    {extracted === 0 ? (
      <p className="max-w-[52ch] text-sm leading-relaxed text-slate-500">
        No documents have reached the pipeline yet. Upload or email one in — the first pass will
        show up here.
      </p>
    ) : diagnosis ? (
      <section aria-labelledby="untouched-heading">
        <h2 id="untouched-heading" className="sr-only">Untouched flow, last 30 days</h2>
        <Figure
          value={`${touchlessPercent}%`}
          state="idle"
          caption={<>
            of the {extracted} extracted document{extracted === 1 ? "" : "s"} published themselves in the last 30 days.
          </>}
        />
        <p className="mt-4 max-w-[62ch] text-sm leading-relaxed text-slate-700">
          {diagnosis.text}{" "}
          <Link href={diagnosis.href} className="font-medium text-emerald-700 underline-offset-2 hover:text-emerald-800 hover:underline">
            {diagnosis.linkLabel} →
          </Link>
        </p>
      </section>
    ) : (
      <>
        <Panel title="The last 30 days">
          <section className="grid gap-8 md:grid-cols-[minmax(0,300px)_minmax(0,1fr)] md:items-center">
            <Figure
              value={`${touchlessPercent}%`}
              caption={<>
                {metrics.touchless.totalPushedTouchless} of {extracted} document{extracted === 1 ? "" : "s"} published themselves.
              </>}
            />
            <Funnel
              total={extracted}
              stages={[
                { label: "Extracted", value: extracted },
                { label: "Passed every check", value: metrics.touchless.totalReady },
                { label: "Synced untouched", value: metrics.touchless.totalPushedTouchless },
              ]}
            />
          </section>
        </Panel>

        <div className="grid gap-x-10 gap-y-10 md:grid-cols-2 lg:grid-cols-3">
          {/* Every panel below is a 30-day snapshot, not a live count — the scope now sits in
              each title so a reader never has to hold "is this now or the last month?" in their
              head. The old ambiguity was the source of the on-screen contradiction with the
              spine (which is live). */}
          <Panel title="Where they landed · last 30 days">
            <Ledger>
              <LedgerRow label="Approved — ready to sync" value={metrics.readiness.ready} share={share(metrics.readiness.ready)} state="auto" href={`/workspaces/${workspaceId}/pipeline?stage=approved`} />
              <LedgerRow label="Blocked in Review" value={metrics.readiness.blocked} share={share(metrics.readiness.blocked)} state="blocked" href={`/workspaces/${workspaceId}/pipeline?stage=review`} />
              <LedgerRow label="Still in Inbox" value={metrics.readiness.pending} share={share(metrics.readiness.pending)} state="idle" href={`/workspaces/${workspaceId}/pipeline?stage=inbox`} />
            </Ledger>
          </Panel>

          <Panel title="Policy decisions · last 30 days">
            {policyTotal === 0
              ? <p className="text-[13px] leading-relaxed text-slate-500">No documents were checked against a policy in the last 30 days.</p>
              : <Ledger>
                  <LedgerRow label="Approved" value={metrics.policyVerdicts.pass} state="auto" />
                  <LedgerRow label="Rejected" value={metrics.policyVerdicts.violation} state="blocked" />
                  <LedgerRow
                    label="Could not be evaluated"
                    value={metrics.policyVerdicts.error}
                    state={metrics.policyVerdicts.error > 0 ? "waiting" : "idle"}
                    note={metrics.policyVerdicts.error > 0 ? "Sent to a reviewer instead of publishing." : undefined}
                  />
                </Ledger>}
          </Panel>

          <Panel title="Matching · last 30 days">
            {matchTotal === 0
              ? <p className="text-[13px] leading-relaxed text-slate-500">No documents to match yet.</p>
              : <Ledger>
                  <LedgerRow
                    label="Matched to a PO, receipt or bank line"
                    value={`${matchPercent}%`}
                    note={`${metrics.matchCoverage.matchedDocuments} of ${matchTotal}`}
                    share={metrics.matchCoverage.matchRate}
                    state="auto"
                  />
                  <LedgerRow
                    label="Unmatched"
                    value={matchTotal - metrics.matchCoverage.matchedDocuments}
                    state="idle"
                  />
                </Ledger>}
          </Panel>
        </div>
      </>
    )}
  </AutomationFrame>
}

import type { ReactNode } from "react"

/** #208: the settings-toggle primitive every admin checkbox in Settings/Automation is required to
 * go through. `explanation` isn't optional — a toggle whose consequence isn't spelled out in one
 * sentence is exactly the failure mode #187/#208 are closing off (an admin flips a switch with no
 * idea what it actually does until something breaks). Generalizes the checkbox-plus-blurb markup
 * `components/settings/automation-config-form.tsx` already used for "The policy check has to
 * pass" / "Any warning stops it, not just a failure" onto one component so a new toggle can't
 * skip the explanation by copy-pasting a bare `<input type="checkbox">`.
 *
 * `variant="block"` (default) is the stacked label-then-explanation form used in a Panel's
 * divide-y list. `variant="inline"` is for a toggle that has to fit in a dense row (e.g. an
 * amount band's "Trusted suppliers only") — the explanation still renders, as a title tooltip and
 * a screen-reader-only sentence, so cramped layout is never a reason to drop it. */
export function SettingToggle({ id, label, explanation, checked, onChange, disabled, variant = "block" }: {
  id: string
  label: ReactNode
  /** One sentence: what changes, or what the workspace is trading off, when this is on. */
  explanation: string
  checked: boolean
  onChange: (checked: boolean) => void
  disabled?: boolean
  variant?: "block" | "inline"
}) {
  if (variant === "inline") {
    return (
      <label htmlFor={id} className="flex items-center gap-2 pb-2.5 text-[13px] text-slate-700" title={explanation}>
        <input
          id={id}
          type="checkbox"
          checked={checked}
          disabled={disabled}
          onChange={(e) => onChange(e.target.checked)}
          className="h-4 w-4 accent-emerald-700"
        />
        <span>{label}</span>
        <span className="sr-only"> — {explanation}</span>
      </label>
    )
  }

  return (
    <label htmlFor={id} className="flex cursor-pointer items-start gap-3 py-3 first:pt-0">
      <input
        id={id}
        type="checkbox"
        checked={checked}
        disabled={disabled}
        onChange={(e) => onChange(e.target.checked)}
        className="mt-0.5 h-4 w-4 accent-emerald-700"
      />
      <span>
        <span className="block text-sm text-slate-900">{label}</span>
        <span className="block text-xs text-slate-500">{explanation}</span>
      </span>
    </label>
  )
}

import { AutomationConfigForm } from "@/components/settings/automation-config-form"
import { AutomationFrame } from "@/components/automation/automation-ui"
import { getCurrentUser } from "@/lib/auth"
import { getWorkspaceCapabilities, requireModule } from "@/lib/modules/capabilities"
import { decimalToNumberOrZero } from "@/lib/money"
import { deriveAutonomyLevel, getOrCreateAutomationConfig } from "@/models/automation-config"
import { countOpenReviewTasks } from "@/models/review-tasks"
import { requireWorkspaceRole } from "@/models/workspaces"
import { notFound } from "next/navigation"

export const dynamic = "force-dynamic"

/** Phase 6, folded into /automation as the "Settings" tab: expose WorkspaceAutomationConfig
 * as Ramp's graduated autonomy slider (Suggest → Auto with approval → Touchless). Owner-only. */
export default async function AutomationSettingsPage({ params }: { params: Promise<{ workspaceId: string }> }) {
  const { workspaceId } = await params
  const user = await getCurrentUser()
  const membership = await requireWorkspaceRole(workspaceId, user.id)
  await requireModule(workspaceId, "touchless-automation")
  if (membership.role !== "owner") notFound()

  const capabilities = await getWorkspaceCapabilities(workspaceId)
  const reviewEnabled = capabilities.has("review-queue")
  const [config, reviewCount] = await Promise.all([
    getOrCreateAutomationConfig(workspaceId),
    reviewEnabled ? countOpenReviewTasks(workspaceId) : 0,
  ])
  const level = deriveAutonomyLevel(config)

  return <AutomationFrame
    workspaceId={workspaceId}
    active="settings"
    reviewCount={reviewCount}
    reviewEnabled={reviewEnabled}
    status="How much of the coding and review pipeline is allowed to finish without a person clicking Approve."
  >
    <AutomationConfigForm
      workspaceId={workspaceId}
      initial={{
        level,
        minConfidence: config.minConfidence,
        qaSampleRate: config.qaSampleRate,
        requirePolicyPass: config.requirePolicyPass,
        blockOnWarnChecks: config.blockOnWarnChecks,
        policyText: config.policyText,
        amountBands: normalizeAmountBands(config.amountBands),
      }}
    />
  </AutomationFrame>
}

function normalizeAmountBands(raw: unknown): Array<{ min: number; max: number | null; minConfidence: number; requireVerifiedSupplier?: boolean }> {
  if (!Array.isArray(raw)) return []
  const rows: Array<{ min: number; max: number | null; minConfidence: number; requireVerifiedSupplier?: boolean }> = []
  for (const item of raw) {
    if (!item || typeof item !== "object") continue
    const rec = item as Record<string, unknown>
    const min = decimalToNumberOrZero(rec.min as never)
    const max = rec.max == null ? null : decimalToNumberOrZero(rec.max as never)
    const minConfidence = decimalToNumberOrZero(rec.minConfidence as never)
    if (Number.isFinite(min) && Number.isFinite(minConfidence)) {
      rows.push({ min, max, minConfidence, requireVerifiedSupplier: rec.requireVerifiedSupplier === true })
    }
  }
  return rows
}

"use client"

import { useEffect, useId, useState } from "react"
import { useRouter } from "next/navigation"
import { toast } from "sonner"

import { estimateTouchlessImpactAction, updateAutomationConfigAction } from "@/app/(app)/workspaces/[workspaceId]/automation/settings/actions"
import { Panel } from "@/components/automation/automation-ui"
import { Button } from "@/components/ui/button"
import { ConfirmDialog } from "@/components/ui/confirm-dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { SettingToggle } from "@/components/settings/setting-toggle"
import type { TouchlessImpactEstimate } from "@/lib/analytics/workspace-analytics"

type Level = "suggest" | "auto" | "touchless"

export type AutomationConfigInitial = {
  level: Level
  minConfidence: number
  qaSampleRate: number
  requirePolicyPass: boolean
  blockOnWarnChecks: boolean
  policyText: string | null
  amountBands: Array<{ min: number; max: number | null; minConfidence: number; requireVerifiedSupplier?: boolean }>
}

/** The three rungs, in the order they hand work over. Presented as a ladder rather than a list of
 * radios: the position on the track is the setting, so how far the workspace has gone is legible
 * before any of the labels are read. */
const LEVELS: { value: Level; name: string; blurb: string }[] = [
  { value: "suggest", name: "Suggest", blurb: "The engine codes a document and stops. Every one waits for a reviewer." },
  { value: "auto", name: "Auto with approval", blurb: "Coding is applied for you. A reviewer confirms it with a single click." },
  { value: "touchless", name: "Touchless", blurb: "Documents the engine is confident about publish themselves. The rest still route to review." },
]

/** Clamp to [0, 1] — the domain every confidence-shaped field in this form shares. Applied on
 * blur rather than on every keystroke so a workspace can still type "0." while composing a
 * decimal without the field fighting them for each character. */
const clamp01 = (n: number) => Math.min(1, Math.max(0, n))

/** A comparable fingerprint of everything the form can change, so "has this been edited since
 * the last save" doesn't need a field-by-field diff. Settings used to have a single Save at the
 * bottom of a long form with nothing telling a reviewer they had unsaved edits if they scrolled
 * away or navigated off. */
type SnapshotInput = {
  level: Level
  minConfidence: number
  qaSampleRate: number
  requirePolicyPass: boolean
  blockOnWarnChecks: boolean
  policyText: string
  amountBands: AutomationConfigInitial["amountBands"]
}
const snapshot = (v: SnapshotInput) => JSON.stringify(v)

function AmountBandRow({ band, onChange, onRemove }: {
  band: { min: number; max: number | null; minConfidence: number; requireVerifiedSupplier?: boolean }
  onChange: (patch: Partial<typeof band>) => void
  onRemove: () => void
}) {
  const minId = useId()
  const maxId = useId()
  const confId = useId()
  const trustedId = useId()
  const invertedRange = band.max !== null && band.max < band.min
  return <div className="rounded-md border border-[#e6ebf1] p-4">
    <div className="grid grid-cols-1 items-end gap-3 sm:grid-cols-[1fr_1fr_1fr_auto_auto]">
      <div>
        <Label htmlFor={minId} className="text-xs text-slate-500">From</Label>
        <Input id={minId} type="number" min={0} step="0.01" value={band.min} onChange={(e) => onChange({ min: Number(e.target.value) })} className="mt-1 tabular-nums" />
      </div>
      <div>
        <Label htmlFor={maxId} className="text-xs text-slate-500">Up to</Label>
        <Input
          id={maxId}
          type="number"
          min={0}
          step="0.01"
          value={band.max ?? ""}
          placeholder="No cap"
          onChange={(e) => onChange({ max: e.target.value === "" ? null : Number(e.target.value) })}
          aria-invalid={invertedRange || undefined}
          className={`mt-1 tabular-nums ${invertedRange ? "border-red-400 focus-visible:ring-red-400" : ""}`}
        />
      </div>
      <div>
        <Label htmlFor={confId} className="text-xs text-slate-500">Confidence needed</Label>
        <Input
          id={confId}
          type="number"
          min={0}
          max={1}
          step={0.01}
          value={band.minConfidence}
          onChange={(e) => onChange({ minConfidence: Number(e.target.value) })}
          onBlur={(e) => onChange({ minConfidence: clamp01(Number(e.target.value)) })}
          className="mt-1 tabular-nums"
        />
      </div>
      <SettingToggle
        id={trustedId}
        variant="inline"
        label="Trusted suppliers only"
        explanation="Only a supplier you've already verified qualifies for this band's lower confidence bar."
        checked={band.requireVerifiedSupplier ?? false}
        onChange={(checked) => onChange({ requireVerifiedSupplier: checked || undefined })}
      />
      <button type="button" onClick={onRemove} className="pb-2.5 text-[13px] font-medium text-red-700 hover:underline">
        Remove
      </button>
    </div>
    {invertedRange && <p className="mt-2 text-xs text-red-600">&ldquo;Up to&rdquo; must be at least &ldquo;From&rdquo;.</p>}
  </div>
}

export function AutomationConfigForm({ workspaceId, initial }: { workspaceId: string; initial: AutomationConfigInitial }) {
  const router = useRouter()
  const [pending, setPending] = useState(false)
  const [level, setLevel] = useState<Level>(initial.level)
  const [minConfidence, setMinConfidence] = useState(initial.minConfidence)
  const [qaSampleRate, setQaSampleRate] = useState(initial.qaSampleRate)
  const [requirePolicyPass, setRequirePolicyPass] = useState(initial.requirePolicyPass)
  const [blockOnWarnChecks, setBlockOnWarnChecks] = useState(initial.blockOnWarnChecks)
  const [policyText, setPolicyText] = useState(initial.policyText ?? "")
  const [amountBands, setAmountBands] = useState(initial.amountBands)
  const minConfidenceId = useId()
  const qaSampleRateId = useId()

  // The Touchless confirm step: opened instead of saving directly when the switch is INTO
  // touchless from something else — the one change in this form that lets documents publish
  // with nobody looking at them. Toggling QA rate or editing a band doesn't need this weight;
  // this one action does.
  const [touchlessConfirm, setTouchlessConfirm] = useState<{ open: boolean; loading: boolean; estimate: TouchlessImpactEstimate | null }>({ open: false, loading: false, estimate: null })

  const [savedSnapshot, setSavedSnapshot] = useState(() => snapshot({
    level: initial.level, minConfidence: initial.minConfidence, qaSampleRate: initial.qaSampleRate,
    requirePolicyPass: initial.requirePolicyPass, blockOnWarnChecks: initial.blockOnWarnChecks,
    policyText: initial.policyText ?? "", amountBands: initial.amountBands,
  }))
  const currentSnapshot = snapshot({ level, minConfidence, qaSampleRate, requirePolicyPass, blockOnWarnChecks, policyText, amountBands })
  const dirty = currentSnapshot !== savedSnapshot

  useEffect(() => {
    if (!dirty) return
    const handler = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = "" }
    window.addEventListener("beforeunload", handler)
    return () => window.removeEventListener("beforeunload", handler)
  }, [dirty])

  const addBand = () => setAmountBands([...amountBands, { min: 0, max: null, minConfidence: 0.85 }])
  const removeBand = (i: number) => setAmountBands(amountBands.filter((_, idx) => idx !== i))
  const updateBand = (i: number, patch: Partial<typeof amountBands[number]>) =>
    setAmountBands(amountBands.map((b, idx) => (idx === i ? { ...b, ...patch } : b)))

  const bandsInvalid = amountBands.some((b) => b.max !== null && b.max < b.min)

  const persist = async () => {
    setPending(true)
    try {
      const result = await updateAutomationConfigAction({
        workspaceId,
        patch: {
          autonomyLevel: level,
          minConfidence,
          qaSampleRate,
          requirePolicyPass,
          blockOnWarnChecks,
          policyText: policyText.trim() || null,
          amountBands,
        },
      })
      if ("error" in result) {
        toast.error(result.error)
      } else {
        toast.success("Controls settings saved")
        setSavedSnapshot(currentSnapshot)
        router.refresh()
      }
    } finally {
      setPending(false)
    }
  }

  const submit = async () => {
    if (bandsInvalid) {
      toast.error("Fix the confidence-by-amount bands before saving — \"Up to\" must be at least \"From\".")
      return
    }
    if (level === "touchless" && initial.level !== "touchless") {
      setTouchlessConfirm({ open: true, loading: true, estimate: null })
      const result = await estimateTouchlessImpactAction({ workspaceId, minConfidence })
      setTouchlessConfirm({ open: true, loading: false, estimate: "ok" in result ? result.estimate : null })
      return
    }
    await persist()
  }

  const confirmTouchless = async () => {
    setTouchlessConfirm({ open: false, loading: false, estimate: null })
    await persist()
  }

  const reachedIndex = LEVELS.findIndex((l) => l.value === level)
  const touchless = level === "touchless"

  return <div className="space-y-10">
    <fieldset>
      <legend className="sr-only">Autonomy level</legend>
      <div className="grid gap-px overflow-hidden rounded-md border border-[#e6ebf1] bg-[#e6ebf1] sm:grid-cols-3">
        {LEVELS.map((option, index) => {
          const selected = level === option.value
          const reached = index <= reachedIndex
          const blurbId = `level-blurb-${option.value}`
          return (
            <label
              key={option.value}
              className={`group relative cursor-pointer p-4 transition-colors focus-within:outline focus-within:outline-2 focus-within:-outline-offset-2 focus-within:outline-emerald-600 ${selected ? "bg-emerald-50" : "bg-white hover:bg-slate-50"}`}
            >
              {/* The rung marker: filled up to the level in force, so the ladder reads left to right. */}
              <span className={`mb-3 block h-1 rounded-full ${reached ? "bg-emerald-600" : "bg-slate-200"}`} aria-hidden />
              <span className="flex items-baseline gap-2">
                <input
                  type="radio"
                  name="level"
                  value={option.value}
                  checked={selected}
                  onChange={() => setLevel(option.value)}
                  aria-label={option.name}
                  aria-describedby={blurbId}
                  className="sr-only"
                />
                <span className={`text-sm font-semibold ${selected ? "text-emerald-900" : "text-slate-900"}`}>{option.name}</span>
                {selected && <span className="text-xs font-medium text-emerald-700">In force</span>}
              </span>
              <span id={blurbId} className="mt-1 block text-[13px] leading-relaxed text-slate-600">{option.blurb}</span>
            </label>
          )
        })}
      </div>
    </fieldset>

    <div className={touchless ? "space-y-10" : "space-y-10 opacity-55"}>
      {!touchless && (
        <p className="rounded-md border border-dashed border-[#dbe3ec] px-4 py-3 text-[13px] text-slate-600">
          These control what counts as confident enough to publish, so they only take effect at Touchless.
          You can set them up now and switch the level when you are ready.
        </p>
      )}

      <Panel title="Confidence to publish" note="A document has to clear this bar before it can go out without a reviewer.">
        <div className="grid gap-6 sm:grid-cols-2">
          <div>
            <Label htmlFor={minConfidenceId} className="text-[13px]">Minimum confidence</Label>
            <Input
              id={minConfidenceId}
              type="number"
              min={0}
              max={1}
              step={0.01}
              value={minConfidence}
              onChange={(e) => setMinConfidence(Number(e.target.value))}
              onBlur={(e) => setMinConfidence(clamp01(Number(e.target.value)))}
              className="mt-1.5 tabular-nums"
            />
            <p className="mt-1.5 text-xs text-slate-500">Between 0 and 1. Most workspaces settle near 0.90.</p>
          </div>
          <div>
            <Label htmlFor={qaSampleRateId} className="text-[13px]">QA sample rate</Label>
            <Input
              id={qaSampleRateId}
              type="number"
              min={0}
              max={1}
              step={0.01}
              value={qaSampleRate}
              onChange={(e) => setQaSampleRate(Number(e.target.value))}
              onBlur={(e) => setQaSampleRate(clamp01(Number(e.target.value)))}
              className="mt-1.5 tabular-nums"
            />
            <p className="mt-1.5 text-xs text-slate-500">
              How much of the published work is spot-checked anyway. 0.05 sends one in twenty to a reviewer without holding it up.
            </p>
          </div>
        </div>
      </Panel>

      <Panel title="What blocks a publish" note="Conditions that send a document to review no matter how confident the coding is.">
        <div className="divide-y divide-[#f1f5f9]">
          <SettingToggle
            id="requirePolicyPass"
            label="The policy check has to pass"
            explanation="A document the policy rejects, or that the check could not evaluate, goes to a person."
            checked={requirePolicyPass}
            onChange={setRequirePolicyPass}
          />
          <SettingToggle
            id="blockOnWarnChecks"
            label="Any warning stops it, not just a failure"
            explanation="Stricter: arithmetic and duplicate warnings hold the document back too."
            checked={blockOnWarnChecks}
            onChange={setBlockOnWarnChecks}
          />
        </div>
      </Panel>

      <Panel title="Policy" note="Written in plain language and checked against every document before it publishes.">
        <Label htmlFor="policyText" className="sr-only">Policy</Label>
        <Textarea
          id="policyText"
          rows={4}
          value={policyText}
          onChange={(e) => setPolicyText(e.target.value)}
          placeholder="Expenses over $1,000 need a receipt attached."
        />
        <p className="mt-1.5 text-xs text-slate-500">Leave this empty and no policy check runs.</p>
      </Panel>

      <Panel
        title="Confidence by amount"
        note="A small invoice from a supplier you trust can clear a lower bar than a large one. Bands are read top to bottom and the first match wins."
      >
        {amountBands.length === 0
          ? <div className="rounded-md border border-dashed border-[#dbe3ec] px-4 py-6 text-center">
              <p className="text-sm text-slate-600">Every document is held to the workspace minimum above.</p>
              <button type="button" onClick={addBand} className="mt-2 text-sm font-medium text-emerald-700 underline underline-offset-4 hover:text-emerald-800">
                Add a band
              </button>
            </div>
          : <div className="space-y-3">
              {amountBands.map((band, i) => (
                <AmountBandRow key={i} band={band} onChange={(patch) => updateBand(i, patch)} onRemove={() => removeBand(i)} />
              ))}
              <button type="button" onClick={addBand} className="text-sm font-medium text-emerald-700 underline underline-offset-4 hover:text-emerald-800">
                Add a band
              </button>
            </div>}
      </Panel>
    </div>

    <div className="flex items-center gap-3 border-t border-[#e6ebf1] pt-5">
      <Button onClick={() => void submit()} disabled={pending || bandsInvalid}>{pending ? "Saving" : "Save changes"}</Button>
      {dirty && !pending && <span className="inline-flex items-center gap-1.5 text-xs font-medium text-amber-700">
        <span className="h-1.5 w-1.5 rounded-full bg-amber-500" aria-hidden="true" />
        Unsaved changes
      </span>}
      {bandsInvalid && <p className="text-xs text-red-600">Fix the confidence-by-amount bands above before saving.</p>}
    </div>

    <ConfirmDialog
      open={touchlessConfirm.open}
      busy={pending}
      title="Switch to Touchless?"
      description={`At a confidence bar of ${minConfidence.toFixed(2)}, documents the engine is that sure about will publish without a reviewer looking at them.`}
      confirmLabel={pending ? "Switching…" : "Switch to Touchless"}
      onConfirm={() => void confirmTouchless()}
      onCancel={() => setTouchlessConfirm({ open: false, loading: false, estimate: null })}
    >
      <div className="rounded-md border border-[#e6ebf1] bg-slate-50 px-3 py-2.5 text-[13px] text-slate-700">
        {touchlessConfirm.loading
          ? "Estimating from the last 30 days…"
          : touchlessConfirm.estimate
            ? touchlessConfirm.estimate.totalRecent === 0
              ? "No documents in the last 30 days to estimate from — this workspace's own history will start filling in as new ones arrive."
              : <>
                Of the last 30 days' <strong className="tabular-nums">{touchlessConfirm.estimate.totalRecent}</strong> documents,{" "}
                about <strong className="tabular-nums">{touchlessConfirm.estimate.eligible}</strong> would have cleared this bar on extraction confidence alone.
                <span className="mt-1 block text-[11px] text-slate-500">An estimate — checks, policy, and supplier cold-start can still hold a document back even past this line.</span>
              </>
            : "Couldn't estimate the impact right now — you can still switch, or cancel and try again."}
      </div>
    </ConfirmDialog>
  </div>
}

"use client"

import { AlertTriangle, Landmark, Library, ListChecks, Settings } from "lucide-react"
import Link from "next/link"
import { usePathname } from "next/navigation"

/** Mobile bottom tab bar. Four slots, the interim shape decided on #237 until #232 gives the
 * phone its two-card home: Invoices (the workspace home — CONTEXT.md), Exceptions, Finance (when
 * the ledger integration is enabled) or Archive as the fallback third slot, then Settings. The
 * last slot is named for where it goes; the old "More" promised a menu that never existed.
 *
 * Hidden on /sheet and /documents/ — those surfaces get their full viewport on a phone; users
 * navigate back through the surface's own header. */
export function MobileTabBar({ workspaceId, pipelineReviewCount = 0, openExceptionsCount = 0, accountingEnabled = false }: {
  workspaceId: string
  pipelineReviewCount?: number
  /** #210 / #238: countOpenExceptions — the same badge the rail's Exceptions entry carries. */
  openExceptionsCount?: number
  accountingEnabled?: boolean
}) {
  const pathname = usePathname()
  if (pathname.endsWith("/sheet") || pathname.includes("/documents/")) return null

  const base = `/workspaces/${workspaceId}`
  const thirdSlot = accountingEnabled
    ? { href: `${base}/finance`, label: "Finance", icon: Landmark, badge: undefined as number | undefined }
    : { href: `${base}/library`, label: "Archive", icon: Library, badge: undefined as number | undefined }

  const tabs = [
    { href: `${base}/invoices`, label: "Invoices", icon: ListChecks, badge: pipelineReviewCount > 0 ? pipelineReviewCount : undefined },
    { href: `${base}/exceptions`, label: "Exceptions", icon: AlertTriangle, badge: openExceptionsCount > 0 ? openExceptionsCount : undefined },
    thirdSlot,
    { href: `${base}/settings/workspace`, label: "Settings", icon: Settings, badge: undefined as number | undefined },
  ]

  return <nav aria-label="Primary workspace navigation" className="fixed inset-x-0 bottom-0 z-40 grid grid-cols-4 items-center border-t border-[#eef2f6] bg-[rgba(255,255,255,0.94)] px-2 pb-5 pt-2 backdrop-blur-[10px] md:hidden">
    {tabs.map((tab) => {
      const active = pathname === tab.href
        || pathname.startsWith(`${tab.href}/`)
        || (tab.label === "Settings" && pathname.startsWith(`${base}/settings`))
        || (tab.label === "Invoices" && (pathname.startsWith(`${base}/pipeline`) || pathname.startsWith(`${base}/documents`) || pathname.startsWith(`${base}/review`) || pathname.startsWith(`${base}/bills`)))
        || (tab.label === "Finance" && pathname.startsWith(`${base}/accounting`))
      // Same cap as the rail badge: three digits of "99+" reads; four digits of a real count does not.
      const badge = tab.badge == null ? null : tab.badge > 99 ? "99+" : String(tab.badge)
      return <Link key={tab.href} href={tab.href}
        aria-current={active ? "page" : undefined}
        className={`relative flex flex-col items-center gap-1 rounded-md p-1 text-[11px] outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2 ${active ? "font-semibold text-emerald-700" : "font-medium text-slate-500"}`}>
        <tab.icon className="h-[21px] w-[21px]" />
        {tab.label}
        {/* After the label in the DOM so it is announced as "Invoices, 6 waiting"; positioned by the icon. */}
        {badge != null && <span className="absolute left-[calc(50%+8px)] top-0 flex h-4 min-w-4 items-center justify-center rounded-full bg-indigo-600 px-1 text-[10px] font-bold text-white tabular-nums"><span className="sr-only">, </span>{badge}<span className="sr-only"> waiting</span></span>}
      </Link>
    })}
  </nav>
}

// Impeccable in-page detector runner (#225). Needs `playwright` resolvable from the cwd it runs in
// (install it in the session scratchpad, run from there: `node <repo>/scripts/dev/detect-in-page.mjs …`)
// and `impeccable live-server --background` on :8400. Prints per-width counts; --verbose lists each finding.
// Usage: node detect.mjs <label> <url> [--click=<selector>] [--shot=<file>] [--widths=1440,390]
// Injects impeccable's in-page detector into the running dev server page and prints counts.
import { chromium } from "playwright"

const [label, url, ...rest] = process.argv.slice(2)
const opt = Object.fromEntries(rest.map((a) => { const i = a.indexOf("="); const k = a.replace(/^--/, "").split("=")[0]; const v = i >= 0 ? a.slice(i + 1) : undefined; return [k, v ?? true] }))
const widths = (opt.widths ?? "1440,390").split(",").map(Number)
const browser = await chromium.launch()
const out = []
for (const width of widths) {
  const page = await browser.newPage({ viewport: { width, height: width < 600 ? 844 : 900 } })
  const errors = []
  page.on("pageerror", (e) => errors.push(String(e.message)))
  await page.goto(url, { waitUntil: "networkidle", timeout: 60000 })
  if (opt.click) {
    await page.mouse.move(width / 2, 400)
    await page.locator(opt.click).first().click()
    if (opt.wait) await page.locator(opt.wait).first().waitFor({ timeout: 60000 }).catch((e) => console.log("wait failed:", e.message.split("\n")[0]))
    await page.waitForTimeout(800)
    await page.waitForLoadState("networkidle")
  }
  if (opt.key) { await page.keyboard.press(opt.key); await page.waitForTimeout(500) }
  if (opt.shot && opt.nodetect) { await page.screenshot({ path: opt.shot.replace(".png", `-${width}.png`), fullPage: false }); await page.close(); continue }
  await page.addScriptTag({ url: "http://localhost:8400/detect.js" })
  await page.waitForTimeout(800)
  const findings = await page.evaluate(async () => {
    const f = await window.impeccableDetectAsync({})
    return f
  })
  const flat = []
  for (const group of findings) for (const f of group.findings ?? []) flat.push({ type: f.type || f.id, detail: (f.detail || f.snippet || "").slice(0, 140), el: group.el?.slice?.(0, 100) ?? group.selector ?? "" })
  const byType = {}
  for (const f of flat) byType[f.type] = (byType[f.type] ?? 0) + 1
  out.push({ label, width, count: flat.length, byType, errors })
  if (opt.shot) await page.screenshot({ path: opt.shot.replace(".png", `-${width}.png`), fullPage: false })
  if (opt.verbose) for (const f of flat) console.log(`  [${width}] ${f.type}: ${f.detail} :: ${f.el}`)
  await page.close()
}
await browser.close()
for (const o of out) console.log(`${o.label} @${o.width}: ${o.count} findings ${JSON.stringify(o.byType)}${o.errors.length ? " pageErrors=" + JSON.stringify(o.errors.slice(0, 2)) : ""}`)

