// Update map #226 for #231: append a Decisions-so-far line, graduate fog, retarget fog that pointed at #231.
import { execFileSync } from "node:child_process"
import fs from "node:fs"
const gh = (...a) => execFileSync("gh", a, { encoding: "utf8", maxBuffer: 1e7 })
let body = gh("issue", "view", "226", "--json", "body", "--jq", ".body")
const before = body

const decision = `- [Shape the Admin area: Configuration, Approval Flows, Mismatch Flows, Users, Companies (#231)](https://github.com/petrose99/docubite/issues/231) (grilling, autopilot; incumbent Settings+Controls critique 23/40): **Workspace is the Company**, Organization is additive above it and never grants entity access ([ADR 0002](https://github.com/petrose99/docubite/blob/codex/post-login-ux-implementation/docs/adr/0002-organization-above-workspace-workspace-is-the-company.md)); two minimal role axes (org \`admin|member\`, entity \`owner|reviewer|member\` unchanged); one rail item **Admin** at the bottom, Controls leaves the spine and folds in; Vic's two groups — Organization (Dashboard at ≥2 companies · Companies · Users) and ‹Company› (Configuration · Approval Flows · PO Mismatch Flows · Suppliers · Integrations); the per-type field table drives the Detail pane *and* each queue's system-view default columns; Default approval flow (off by default) and a mismatch approver with tolerances; Users and Companies on the Queue-screen shell; Controls' Panel/Ledger grammar is the admin grammar, left nav not tabs, explicit Save on a sticky bar; "Jurisdiction" → Tax; Security and Reset tour move to the account menu; Admin is desktop-only, the phone's 4th tab becomes Account. Glossary: Company, Organization, Admin, Configuration. Execution: [#252](https://github.com/petrose99/docubite/issues/252) shell + Configuration → [#253](https://github.com/petrose99/docubite/issues/253) Flows, [#254](https://github.com/petrose99/docubite/issues/254) Organization/Users (waits on [#255](https://github.com/petrose99/docubite/issues/255) scope-guard gap); owner sign-off on unplugging Settings › Templates and › Reports: [#256](https://github.com/petrose99/docubite/issues/256).`

body = body.replace(/\n## Not yet specified/, `\n${decision}\n\n## Not yet specified`)

// Fog graduated or retargeted
const drop = [
  /- Metadata-driven columns:[^\n]*\n/,
  /- Vic's per-entity Admin Dashboard[^\n]*\n/,
  /- The multi-workspace day[^\n]*\n/,
]
for (const re of drop) body = body.replace(re, "")
body = body.replace(
  /- A payments approval flow \(who may approve a batch beyond "any owner", amount thresholds, a second signature\) and a payments role for members: chartable once Admin Approval Flows and Users \(#231\) exist;/,
  '- A payments approval flow (who may approve a batch beyond "any owner", amount thresholds, a second signature) and a payments role for members: chartable once Approval Flows (#253) and Users (#254) ship;'
)
body = body.replace(
  /Revisit only on operator demand or once Admin Configuration \(#231\) exists\./,
  "Revisit only on operator demand or once Admin › PO Mismatch Flows (#253) ships."
)
body = body.replace(
  /- "Is the bank reconciled\?" is answered twice, on Health Checks and on Close; which one owns it sharpens with #231\./,
  '- "Is the bank reconciled?" is answered twice, on Health Checks and on Close; #231 kept both where they are (secondary rail), so ownership sharpens with Finance\'s shape (#248), not with Admin.'
)
body = body.replace(
  /- Whether DocuBite's queue columns become configuration-driven[^\n]*\n/, ""
)
if (body === before) { console.log("NO CHANGE"); process.exit(1) }
fs.writeFileSync("/tmp/scratch229/map-226-new.md", body)
gh("issue", "edit", "226", "--body-file", "/tmp/scratch229/map-226-new.md")
console.log("updated; length", before.length, "->", body.length)

